// Managed settings, generated by scripts/Build-Schema.ps1 from schema/managed-settings.csv.
// The app never lists settings itself (CLAUDE.md hard rule): everything comes from this file.
import raw from '../../../schema/settings.json';

export type SettingKind = 'Integer' | 'String' | 'Boolean' | 'Choice' | 'Lookup' | 'GuidText' | 'LookupText';

export interface SettingOption { value: number; label: string }

export interface SettingDefinition {
  attribute: string;
  label: string;
  group: string;
  valueColumn: string;
  modeColumn: string;
  kind: SettingKind;
  min?: number | null;
  max?: number | null;
  options?: SettingOption[];
  /** Lookup target table (Lookup, LookupText). */
  target?: string;
  maxLength?: number;
}

export const SETTINGS: SettingDefinition[] = raw as SettingDefinition[];

/** Setting groups in the order they first appear in the CSV. */
export const GROUPS: string[] = SETTINGS.reduce<string[]>((acc, s) => (acc.includes(s.group) ? acc : [...acc, s.group]), []);

export const byAttribute = new Map(SETTINGS.map((s) => [s.attribute, s]));

/** Global choice jhrb_settingmode. */
export const Mode = { Inherit: 632490000, Default: 632490001, Locked: 632490002 } as const;
export type ModeValue = (typeof Mode)[keyof typeof Mode];
export const MODE_NAMES: Record<number, 'Inherit' | 'Default' | 'Locked'> = {
  [Mode.Inherit]: 'Inherit',
  [Mode.Default]: 'Default',
  [Mode.Locked]: 'Locked',
};

/** jhrb_type on jhrb_settingsprofile. */
export const ProfileType = { Global: 632490000, Group: 632490001, User: 632490002 } as const;
export const PROFILE_TYPE_NAMES: Record<number, string> = { 632490000: 'Global', 632490001: 'Group', 632490002: 'User' };

/** jhrb_scopetype on jhrb_profilescope. */
export const ScopeType = { Team: 632490000, BusinessUnit: 632490001 } as const;

export const JobStatus = { Pending: 632490000, Running: 632490001, Completed: 632490002, Failed: 632490003, Cancelled: 632490004 } as const;
export const JOB_STATUS_NAMES: Record<number, string> = { 632490000: 'Pending', 632490001: 'Running', 632490002: 'Completed', 632490003: 'Failed', 632490004: 'Cancelled' };
export const APPLY_MODE_NAMES: Record<number, string> = { 632490000: 'Full', 632490001: 'Locked only', 632490002: 'Auto' };
export const JOB_REASON_NAMES: Record<number, string> = {
  632490000: 'Manual', 632490001: 'Profile change', 632490002: 'New user', 632490003: 'Membership', 632490004: 'Reconcile', 632490005: 'User override',
};
export const LOG_SOURCE_NAMES: Record<number, string> = { 632490000: 'Rollout', 632490001: 'New user', 632490002: 'Reverted', 632490003: 'Admin edit', 632490004: 'Group change' };

/** Display text for a profile column value. */
export function formatValue(def: SettingDefinition, value: unknown): string {
  if (value === null || value === undefined || value === '') return '';
  switch (def.kind) {
    case 'Boolean': return value ? 'Yes' : 'No';
    case 'Choice': return def.options?.find((o) => o.value === Number(value))?.label ?? String(value);
    default: return String(value);
  }
}
